import React from 'react';

/**
 * Props for the {@link Markdown} component.
 *
 * Syntax-highlight token-class contract
 * -------------------------------------
 * `Markdown` is a styling container; it does not tokenize code. A highlighter
 * (server-side, or the `highlight` render prop below) may emit `<span>`s inside
 * fenced code blocks using these classes, each mapped to one semantic token in
 * `markdown.css` so highlighting tracks the active theme:
 *
 *   - `sk-md-tok-keyword`     → accent
 *   - `sk-md-tok-string`      → success
 *   - `sk-md-tok-number`      → info
 *   - `sk-md-tok-comment`     → muted-foreground (italic)
 *   - `sk-md-tok-function`    → foreground (emphasized)
 *   - `sk-md-tok-punctuation` → muted-foreground
 *
 * Wide tables should be wrapped in `<div class="sk-markdown__table-wrap">` so
 * they scroll instead of overflowing.
 */
export interface MarkdownProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Additional CSS class names. */
  className?: string;
  /** Pre-rendered HTML or React nodes to display with markdown styling. */
  children?: React.ReactNode;
  /**
   * Optional transform applied to `children` before rendering — e.g. a syntax
   * highlighter that emits the `sk-md-tok-*` spans documented above. Opt-in:
   * when omitted, `children` render unchanged. The component still does not
   * parse raw markdown; this only post-processes already-provided content.
   */
  highlight?: (children: React.ReactNode) => React.ReactNode;
}

/**
 * Markdown renderer container for AI chat content.
 * Applies `sk-markdown` typography styles to child content.
 * This component does not parse raw markdown; pass pre-rendered HTML or React elements.
 */
export const Markdown = React.forwardRef<HTMLDivElement, MarkdownProps>(
  ({ className, children, highlight, ...rest }, ref) => (
    <div ref={ref} className={`sk-markdown${className ? ` ${className}` : ''}`} {...rest}>
      {highlight ? highlight(children) : children}
    </div>
  ),
);

Markdown.displayName = 'Markdown';

/**
 * skeehn — Markdown Component
 *
 * @component sk-markdown
 * @elements  h1-h6 | p | a | code | pre | ul/ol | li | blockquote | hr | table | img
 * @a11y      Semantic HTML, link underlines, sufficient contrast
 * @design    SANS prose with a real h1-h6 type ramp; mono only for code. Paragraph
 *            rhythm, accent links/markers, readable tables. Editorial, not all-caps mono.
 */

.sk-markdown {
  font-family: var(--sk-font-sans);
  font-size: var(--sk-font-size-base);
  line-height: var(--sk-line-height-relaxed);
  color: hsl(var(--sk-foreground));
  word-wrap: break-word;
  overflow-wrap: break-word;
}

.sk-markdown > *:first-child { margin-top: 0; }
.sk-markdown > *:last-child { margin-bottom: 0; }

/* Headings — SANS, real hierarchy */
.sk-markdown h1, .sk-markdown h2, .sk-markdown h3,
.sk-markdown h4, .sk-markdown h5, .sk-markdown h6 {
  font-family: var(--sk-font-sans);
  font-weight: 600;
  line-height: var(--sk-line-height-tight);
  margin: 1.6em 0 0.5em;
  color: hsl(var(--sk-foreground));
}
.sk-markdown h1 { font-size: var(--sk-font-size-2xl); font-weight: 700; letter-spacing: var(--sk-letter-spacing-tight); }
.sk-markdown h2 { font-size: var(--sk-font-size-xl); letter-spacing: var(--sk-letter-spacing-tight); }
.sk-markdown h3 { font-size: var(--sk-font-size-lg); }
.sk-markdown h4 { font-size: var(--sk-font-size-base); }
.sk-markdown h5, .sk-markdown h6 {
  font-size: var(--sk-font-size-sm);
  font-family: var(--sk-font-mono);
  text-transform: uppercase;
  letter-spacing: var(--sk-letter-spacing-wide);
  color: hsl(var(--sk-muted-foreground));
}

.sk-markdown p { margin: 0 0 1em; }
.sk-markdown strong { font-weight: 700; }
.sk-markdown em { font-style: italic; }

.sk-markdown a {
  color: hsl(var(--sk-accent));
  text-decoration: underline;
  text-underline-offset: 2px;
  text-decoration-thickness: 1px;
}
.sk-markdown a:hover { text-decoration-thickness: 2px; }

/* Inline code — mono accent */
.sk-markdown code:not(pre code) {
  font-family: var(--sk-font-mono);
  font-size: 0.85em;
  padding: 0.12em 0.4em;
  background: hsl(var(--sk-muted));
  border-radius: var(--sk-radius-control);
  color: hsl(var(--sk-accent));
}

/* Fenced code — matches CodeBlock treatment */
.sk-markdown pre {
  margin: 1em 0;
  padding: var(--sk-space-3) var(--sk-space-4);
  background: hsl(var(--sk-surface));
  border: var(--sk-border);
  border-radius: var(--sk-radius-panel);
  overflow-x: auto;
  position: relative;
}
.sk-markdown pre::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image: var(--sk-dither-pattern);
  background-repeat: repeat;
  background-size: 32px 32px;
  opacity: var(--sk-dither-opacity-subtle);
  pointer-events: none;
  border-radius: inherit;
}
.sk-markdown pre code {
  font-family: var(--sk-font-mono);
  font-size: var(--sk-font-size-sm);
  line-height: var(--sk-line-height-relaxed);
  background: none;
  border: none;
  padding: 0;
  color: hsl(var(--sk-foreground));
  position: relative;
  z-index: 1;
}

/* Syntax-highlight token contract.
   A highlighter (or markdown.js) may emit <span class="sk-md-tok-*"> inside a
   fenced code block; each class maps to one semantic token so highlighting
   tracks the active theme. Unhighlighted code stays foreground (rule above).
   These are scoped to .sk-markdown so they apply whether the code lives in a
   bare <pre> (React wrapper) or inside .sk-code-block (markdown.js render). */
.sk-markdown .sk-md-tok-keyword     { color: hsl(var(--sk-accent)); }
.sk-markdown .sk-md-tok-string      { color: hsl(var(--sk-success)); }
.sk-markdown .sk-md-tok-number      { color: hsl(var(--sk-info)); }
.sk-markdown .sk-md-tok-comment     { color: hsl(var(--sk-muted-foreground)); font-style: italic; }
.sk-markdown .sk-md-tok-function    { color: hsl(var(--sk-foreground)); font-weight: 600; }
.sk-markdown .sk-md-tok-punctuation { color: hsl(var(--sk-muted-foreground)); }

/* Lists */
.sk-markdown ul, .sk-markdown ol { margin: 0 0 1em; padding-left: var(--sk-space-6); }
.sk-markdown li { margin: 0.35em 0; }
.sk-markdown ul li::marker { content: "▸ "; color: hsl(var(--sk-accent)); }
.sk-markdown ol li::marker { color: hsl(var(--sk-muted-foreground)); }

/* Blockquote — accent rail */
.sk-markdown blockquote {
  margin: 1em 0;
  padding: var(--sk-space-1) var(--sk-space-4);
  border-left: 3px solid hsl(var(--sk-accent) / 0.6);
  color: hsl(var(--sk-muted-foreground));
}

.sk-markdown hr { margin: 1.6em 0; border: none; border-top: var(--sk-border); }

/* Tables — readable. Wrap scrolls wide tables instead of overflowing the container. */
.sk-markdown__table-wrap { overflow-x: auto; margin: 1em 0; }
.sk-markdown__table-wrap > table { margin: 0; }
.sk-markdown table { width: 100%; margin: 1em 0; border-collapse: collapse; font-size: var(--sk-font-size-sm); }
.sk-markdown th, .sk-markdown td {
  padding: var(--sk-space-2) var(--sk-space-3);
  text-align: left;
  border-bottom: var(--sk-border);
}
.sk-markdown th {
  font-family: var(--sk-font-mono);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: var(--sk-letter-spacing-wide);
  font-size: var(--sk-font-size-xs);
  background: hsl(var(--sk-muted));
  color: hsl(var(--sk-muted-foreground));
}

/* Figures & images */
.sk-markdown img {
  display: block;
  max-width: 100%;
  height: auto;
  border-radius: var(--sk-radius-md);
  border: var(--sk-border);
}
.sk-markdown figure { margin: 1.6em 0; }
.sk-markdown figure img { margin: 0 auto; }
.sk-markdown figcaption {
  margin-top: var(--sk-space-2);
  font-size: var(--sk-font-size-sm);
  line-height: var(--sk-line-height-relaxed);
  color: hsl(var(--sk-muted-foreground));
  text-align: center;
}

/* Loading */
.sk-markdown[data-loading] { position: relative; opacity: 0.6; }
.sk-markdown[data-loading]::after {
  content: "";
  position: absolute;
  inset: 0;
  background-image: var(--sk-dither-pattern);
  background-repeat: repeat;
  opacity: var(--sk-dither-opacity-subtle);
  animation: sk-pulse-dither 1.5s ease-in-out infinite;
  pointer-events: none;
}

/* Skeleton (centralized keyframe) */
.sk-markdown[data-skeleton] > * {
  color: transparent;
  background: linear-gradient(90deg, hsl(var(--sk-muted)) 25%, hsl(var(--sk-secondary)) 50%, hsl(var(--sk-muted)) 75%);
  background-size: 200% 100%;
  animation: sk-shimmer 1.8s ease-in-out infinite;
  border-radius: var(--sk-radius-sm);
  min-height: 1rem;
  margin: var(--sk-space-2) 0;
}

@media print {
  .sk-markdown pre::before { display: none; }
  .sk-markdown a::after { content: " (" attr(href) ")"; font-size: 0.7em; color: hsl(var(--sk-muted-foreground)); }
  .sk-markdown[data-skeleton] { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .sk-markdown[data-loading]::after { animation: none; }
  .sk-markdown[data-skeleton] > * { animation: none; background: hsl(var(--sk-muted)); }
}
